import React, { useEffect, useRef, useState, useMemo } from "react";
import Masonry from "react-masonry-css";
import imagesLoaded from "imagesloaded";
import { ButtonGroup, Button } from "react-bootstrap";

// Simple categories derivation helper
function deriveCategories(items = []) {
  const set = new Set();
  items.forEach((it) => {
    if (it.category) set.add(it.category);
  });
  return Array.from(set);
}

export default function MasonryGallery({ items = [] }) {
  const containerRef = useRef(null);
  const [activeFilter, setActiveFilter] = useState("all");
  const categories = useMemo(() => deriveCategories(items), [items]);

  // filtered items based on activeFilter
  const filtered = useMemo(() => {
    if (activeFilter === "all") return items;
    return items.filter((it) => it.category === activeFilter);
  }, [items, activeFilter]);

  // re-layout masonry after images load
  useEffect(() => {
    if (!containerRef.current) return;
    const imgLoad = imagesLoaded(containerRef.current);
    // Force a reflow when all images are done
    imgLoad.on("always", () => {
      // no-op; react-masonry-css responds to children changes
    });
    return () => imgLoad.off();
  }, [filtered]);

  const breakpointColumnsObj = {
    default: 4,
    1100: 3,
    700: 2,
    480: 1,
  };

  return (
    <div className="masonry-wrapper">
      <div className="masonry-filters text-center mb-3">
        <ButtonGroup aria-label="filters">
          <Button variant={activeFilter === "all" ? "primary" : "outline-primary"} onClick={() => setActiveFilter("all")}>
            All
          </Button>
          {categories.map((c) => (
            <Button key={c} variant={activeFilter === c ? "primary" : "outline-primary"} onClick={() => setActiveFilter(c)}>
              {c}
            </Button>
          ))}
        </ButtonGroup>
      </div>

      <div ref={containerRef} className="masonry-gallery">
        <Masonry breakpointCols={breakpointColumnsObj} className="my-masonry-grid" columnClassName="my-masonry-grid_column">
          {filtered.map((it, idx) => (
            <figure className="masonry-item card" key={idx}>
              <img src={it.img} alt={it.title || `item-${idx}`} loading="lazy" className="card-img-top" />
              <figcaption className="card-body">
                <h5 className="card-title mb-1">{it.title}</h5>
                {it.subtitle ? <p className="card-text small">{it.subtitle}</p> : null}
                {it.price ? <div className="mt-2"><strong>{it.price}</strong></div> : null}
              </figcaption>
            </figure>
          ))}
        </Masonry>
      </div>
    </div>
  );
}
